/**
 * Node model.
 *
 * A prompt document is a flat list of nodes (see ADR-0002): text runs and
 * atomic "chip" nodes (mention, command, variable, attachment, custom).
 *
 * Every node carries a stable instance `key`. It is NOT the entity id —
 * {@link MentionNode}.id identifies the mentioned entity, `key` identifies
 * this particular node instance and stays stable across clones, undo/redo
 * and DOM round-trips (React keys, DOM↔model mapping).
 */
let sequence = 0;
/** Generate a unique node key, e.g. `mention_lx3a_07_f2k9q1`. */
export function createNodeKey(prefix = 'n') {
  sequence += 1;
  return `${prefix}_${Date.now().toString(36)}_${sequence.toString(36)}_${Math.random().toString(36).slice(2, 8)}`;
}
// ---------------------------------------------------------------------------
// Factories
// ---------------------------------------------------------------------------
export function createTextNode(text, key = createNodeKey('text')) {
  return {
    type: 'text',
    key,
    text
  };
}
export function createMentionNode(input, key = createNodeKey('mention')) {
  return {
    type: 'mention',
    key,
    ...input
  };
}
export function createCommandNode(input, key = createNodeKey('command')) {
  return {
    type: 'command',
    key,
    ...input
  };
}
export function createVariableNode(input, key = createNodeKey('variable')) {
  return {
    type: 'variable',
    key,
    name: input.name,
    ...(input.value !== undefined ? {
      value: input.value
    } : {})
  };
}
export function createAttachmentNode(input, key = createNodeKey('attachment')) {
  return {
    type: 'attachment',
    key,
    ...input
  };
}
export function createCustomNode(input, key = createNodeKey(input.nodeType || 'custom')) {
  return {
    type: 'custom',
    key,
    plugin: input.plugin,
    nodeType: input.nodeType,
    data: input.data
  };
}
/** Assign a key to a hand-built node that lacks one (e.g. from parsed JSON). */
export function ensureNodeKey(node) {
  return node.key ? node : {
    ...node,
    key: createNodeKey(node.type)
  };
}
// ---------------------------------------------------------------------------
// Guards
// ---------------------------------------------------------------------------
export function isTextNode(node) {
  return node.type === 'text';
}
export function isAtomicNode(node) {
  return node.type !== 'text';
}
export function getNodeType(node) {
  return node.type;
}
/** Lightweight structural validation for documents coming from views / storage. */
export function isPromptNode(value) {
  if (typeof value !== 'object' || value === null) return false;
  const node = value;
  return typeof node.type === 'string' && typeof node.key === 'string' && (node.type !== 'text' || typeof node.text === 'string');
}
